8.query:
fetch bizevents, from:now()-1h
| filter `event.provider` == "banco.core"
| summarize total = count(), by:{bin(timestamp, 2m), canal}

23.query:
fetch bizevents, from:now()-1h
| filter `event.provider` == "banco.auth"
| summarize total = count(), sucesso = countIf(status == "success"), falhas = countIf(status == "failure"), by:{bin(timestamp, 2m)}
